# Paper: arxiv:2503
class Ladder:
    def __init__(self, max_depth=5):
        self.max_depth = max_depth
        self.data = []
    def generate_variants(self, problem, depth=0):
        if depth >= self.max_depth: return [problem]
        variants = [problem]
        for i in range(3):
            s = self._simplify(problem, depth)
            if s and s != problem: variants.extend(self.generate_variants(s, depth+1))
        return variants

# C-SPACE + SOV-SPACE WIRING
class CSOVSpace:
    def __init__(self):
        self.dreams = []
        self.outputs = []
    def observe(self, model, output, family):
        self.outputs.append({"model": model, "output": output[:300], "family": family})
    def dream(self, scenario):
        outcomes = []
        for o in self.outputs[-5:]:
            outcomes.append({"model": o["model"], "outcome": o["output"][:100]})
        self.dreams.append({"scenario": scenario, "outcomes": outcomes})

